static boolean detectCycle(Map<String,List<String>> g) {
    Set<String> visiting = new HashSet<>(), visited = new HashSet<>();
    for (String node : g.keySet()) if (dfs(node, g, visiting, visited)) return true;
    return false;
}
static boolean dfs(String n, Map<String,List<String>> g, Set<String> visiting, Set<String> visited) {
    if (visiting.contains(n)) return true;
    if (visited.contains(n)) return false;
    visiting.add(n);
    for (String dep : g.getOrDefault(n, List.of())) if (dfs(dep, g, visiting, visited)) return true;
    visiting.remove(n); visited.add(n);
    return false;
}

static String resolveNewestWins(List<String> versions) {
    return versions.stream().max((a,b) -> compareVersions(a,b)).orElseThrow();
}
static int compareVersions(String a, String b) {
    String[] pa = a.split("\\."), pb = b.split("\\.");
    for (int i = 0; i < 3; i++) {
        int diff = Integer.parseInt(pa[i]) - Integer.parseInt(pb[i]);
        if (diff != 0) return diff;
    }
    return 0;
}
System.out.println(resolveNewestWins(List.of("2.8.0","2.11.0","2.9.5")));

