static List<String> topologicalOrder(Map<String,List<String>> g) {
    List<String> result = new ArrayList<>();
    Set<String> visited = new HashSet<>();
    for (String n : g.keySet()) visit(n, g, visited, result);
    return result;
}
static void visit(String n, Map<String,List<String>> g, Set<String> visited, List<String> result) {
    if (visited.contains(n)) return;
    visited.add(n);
    for (String dep : g.getOrDefault(n, List.of())) visit(dep, g, visited, result);
    result.add(n);
}

static Map<String,String> generateMultiProjectSkeleton(String rootName, Map<String,List<String>> deps) {
    Map<String,String> files = new LinkedHashMap<>();
    files.put("settings.gradle", "rootProject.name='" + rootName + "'\ninclude(" + String.join(",", deps.keySet().stream().map(k -> "'"+k+"'").toList()) + ")");
    for (var e : deps.entrySet()) {
        StringBuilder sb = new StringBuilder("plugins { id 'java' }\ndependencies {\n");
        for (String dep : e.getValue()) sb.append("    implementation project(':").append(dep).append("')\n");
        sb.append("}");
        files.put(e.getKey() + "/build.gradle", sb.toString());
    }
    return files;
}

static String resolve(Map<String,String> projectProps, String key, String sysKey, String envVar, Map<String,String> gradleProps) {
    if (projectProps.containsKey(key)) return projectProps.get(key);
    String sys = System.getProperty(sysKey);
    if (sys != null) return sys;
    String env = System.getenv(envVar);
    if (env != null) return env;
    return gradleProps.getOrDefault(key, "BRAK");
}

